// Team Performance на дашборде (#5814749d): сумма $ и число работ по техникам, период, разбивка.
// Только просмотр: ничего не создаёт и не меняет. Компания — только «test» (переключать компанию нельзя).
import { expect, Locator, Page, Response } from '@playwright/test';
import { Lang, SALES_JOBS_TITLE, setLanguage } from './dashboard-helpers';

export const TEAM_TITLE: Record<Lang, string> = { en: 'Team Performance', he: 'ביצועי צוות' };
export const RANGE_BUTTON: Record<Lang, string> = { en: 'Select range', he: 'בחר טווח' };
export const ROW_PREFIX: Record<Lang, string> = { en: 'Show the jobs: ', he: 'הצגת העבודות: ' };
/** Пункт меню периода. */
export const RANGE_OPTION: Record<Lang, (days: number) => string> = {
  en: (d) => `Last ${d} Days`,
  he: (d) => `${d} ימים אחרונים`,
};
/** Подпись периода под заголовком виджета. */
export const PERIOD_LABEL: Record<Lang, (days: number) => string> = {
  en: (d) => `Last ${d} days`,
  he: (d) => `אחרונים ${d} ימים`,
};
export const JOBS_DONE_RE: Record<Lang, RegExp> = { en: /^(\d+) jobs? done$/, he: /^(\d+) עבוד(?:ות|ה) בוצע(?:ו|ה)$/ };

export type TeamRow = { name: string; cents: number; jobs: number };
export type RpcCall = { from: string; to: string; body: any[] };

/** «$4,757.22» → 475722 (в центах, без ошибок округления). */
export function moneyToCents(text: string): number {
  const m = text.replace(/\s/g, '').match(/-?\$?-?([\d,]+(?:\.\d+)?)/);
  if (!m) throw new Error(`не сумма: «${text}»`);
  return Math.round(parseFloat(m[1].replace(/,/g, '')) * 100);
}
export const toCents = (n: number) => Math.round(Number(n) * 100);

/** Число дней периода по запросу RPC (p_from..p_to включительно). */
export function periodDays(call: { from: string; to: string }): number {
  return Math.round((Date.parse(call.to) - Date.parse(call.from)) / 86_400_000) + 1;
}

/** dd/mm/yy из YYYY-MM-DD — так период показан в окне разбивки. */
export function ddmmyy(iso: string): string {
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y.slice(2)}`;
}

export const teamWidget = (page: Page, lang: Lang) =>
  page.locator('section.tec-dashboard-section').filter({ has: page.getByRole('heading', { name: TEAM_TITLE[lang], exact: true }) });
export const salesWidget = (page: Page, lang: Lang) =>
  page.locator('section.tec-dashboard-section').filter({ has: page.getByRole('heading', { name: SALES_JOBS_TITLE[lang], exact: true }) });
export const techRows = (page: Page, lang: Lang) =>
  teamWidget(page, lang).getByRole('button', { name: new RegExp(`^${ROW_PREFIX[lang]}`) });

/**
 * Собирает ответы rpc/dashboard_team_performance и rpc/dashboard_sales_chart (с периодом из тела запроса).
 * Подключать ДО page.goto, чтобы не пропустить запросы первой загрузки.
 */
export function trackDashboardRpc(page: Page) {
  const team: RpcCall[] = [];
  const sales: RpcCall[] = [];
  page.on('response', async (r: Response) => {
    const url = r.url();
    const isTeam = /\/rpc\/dashboard_team_performance\b/.test(url);
    const isSales = /\/rpc\/dashboard_sales_chart\b/.test(url);
    if ((!isTeam && !isSales) || r.request().method() !== 'POST' || !r.ok()) return;
    try {
      const req = JSON.parse(r.request().postData() || '{}');
      const body = await r.json();
      (isTeam ? team : sales).push({ from: req.p_from, to: req.p_to, body });
    } catch { /* ответ без тела — пропускаем */ }
  });
  return {
    team,
    sales,
    /** Последний ответ Team Performance за период N дней. */
    async teamFor(days: number): Promise<RpcCall> {
      let hit: RpcCall | undefined;
      await expect.poll(() => (hit = [...team].reverse().find((c) => periodDays(c) === days)) !== undefined,
        { message: `ответ rpc/dashboard_team_performance за ${days} дн.`, timeout: 20_000 }).toBe(true);
      return hit!;
    },
    /** Ответ Sales & Jobs ровно за тот же период (p_from/p_to), что и у Team Performance. */
    async salesFor(period: { from: string; to: string }): Promise<RpcCall> {
      let hit: RpcCall | undefined;
      await expect.poll(() => (hit = [...sales].reverse().find((c) => c.from === period.from && c.to === period.to)) !== undefined,
        { message: `ответ rpc/dashboard_sales_chart за ${period.from}..${period.to}`, timeout: 20_000 }).toBe(true);
      return hit!;
    },
  };
}

/** Открыть /dashboard (язык до загрузки), дождаться обоих виджетов; убедиться, что выбрана компания «test». */
export async function openDashboardTeam(page: Page, lang: Lang) {
  await setLanguage(page, lang);
  await page.goto('/dashboard');
  await expect(teamWidget(page, lang)).toBeVisible();
  await expect(salesWidget(page, lang)).toBeVisible();
  // Только компания «test»: на реальном клиенте тест не идёт (компанию не переключаем).
  await expect(page.locator('header').first().getByText('test', { exact: true }), 'выбрана компания «test»').toBeVisible();
}

/** Открыть меню «…» (Select range) виджета и вернуть его всплывающее окно. */
export async function openRangeMenu(page: Page, widget: Locator, lang: Lang): Promise<Locator> {
  const btn = widget.getByRole('button', { name: RANGE_BUTTON[lang], exact: true });
  await btn.click();
  const id = await btn.getAttribute('aria-controls');
  const pop = id ? page.locator(`[id="${id}"]`) : page.getByRole('dialog').last();
  await expect(pop).toBeVisible();
  return pop;
}

/** Выбрать «Last N Days» в виджете и дождаться ответа его RPC за N дней. */
export async function chooseRange(page: Page, widget: Locator, lang: Lang, days: number, rpc: 'team' | 'sales') {
  const pop = await openRangeMenu(page, widget, lang);
  const re = rpc === 'team' ? /\/rpc\/dashboard_team_performance\b/ : /\/rpc\/dashboard_sales_chart\b/;
  const resp = page.waitForResponse((r) => {
    if (!re.test(r.url()) || r.request().method() !== 'POST') return false;
    try { const b = JSON.parse(r.request().postData() || '{}'); return periodDays({ from: b.p_from, to: b.p_to }) === days; } catch { return false; }
  });
  await pop.getByRole('button', { name: RANGE_OPTION[lang](days), exact: true }).click();
  await resp;
  await expect(pop).toBeHidden();
}

/** Строки виджета, как их видит пользователь: имя, сумма, число работ. */
export async function readTeamRows(page: Page, lang: Lang): Promise<TeamRow[]> {
  const rows = techRows(page, lang);
  const n = await rows.count();
  const out: TeamRow[] = [];
  for (let i = 0; i < n; i++) {
    const p = await rows.nth(i).getByRole('paragraph').allInnerTexts();
    // [имя, $сумма, «N jobs done»]
    const jobsText = p.find((t) => JOBS_DONE_RE[lang].test(t.trim())) ?? '';
    const money = p.find((t) => /\$/.test(t)) ?? '';
    out.push({ name: p[0].trim(), cents: moneyToCents(money), jobs: Number(jobsText.trim().match(JOBS_DONE_RE[lang])?.[1] ?? NaN) });
  }
  return out;
}

/** Ответ RPC Team Performance в виде строк виджета. */
export const rowsFromRpc = (call: RpcCall): TeamRow[] =>
  call.body.map((r: any) => ({ name: String(r.name), cents: toCents(r.total), jobs: Number(r.job_count) }));

/** Дождаться, что строки виджета совпали с ответом RPC (значения обновляются через 250–450 мс после ответа). */
export async function expectRowsMatchRpc(page: Page, lang: Lang, call: RpcCall) {
  const expected = rowsFromRpc(call);
  await expect(techRows(page, lang)).toHaveCount(expected.length);
  await expect.poll(() => readTeamRows(page, lang), { message: 'строки Team Performance = ответ RPC' }).toEqual(expected);
}

/** TOTAL SALES и JOBS DONE виджета Sales & Jobs (числа под графиком). */
export async function readSalesTotals(page: Page, lang: Lang): Promise<{ cents: number; jobs: number }> {
  const totals = salesWidget(page, lang).locator('.tec-sales-totals');
  const spans = await totals.locator('span').allInnerTexts();
  const money = spans.find((t) => /^\s*\$[\d,]+(\.\d+)?\s*$/.test(t)) ?? '';
  const jobs = spans.map((t) => t.trim()).filter((t) => /^\d+$/.test(t));
  return { cents: moneyToCents(money), jobs: Number(jobs[jobs.length - 1]) };
}

export type BreakdownJob = { href: string; jobNo: string; date: string; cents: number; text: string };

/** Открыть разбивку техника и дождаться, что в ней столько работ, сколько в строке. */
export async function openBreakdown(page: Page, lang: Lang, row: TeamRow): Promise<Locator> {
  await teamWidget(page, lang).getByRole('button', { name: `${ROW_PREFIX[lang]}${row.name}`, exact: true }).click();
  const dlg = page.getByRole('dialog', { name: row.name, exact: true });
  await expect(dlg).toBeVisible();
  await expect(dlg.getByRole('listitem')).toHaveCount(row.jobs, { timeout: 20_000 });
  return dlg;
}

export async function readBreakdown(dlg: Locator): Promise<BreakdownJob[]> {
  const links = dlg.getByRole('listitem').getByRole('link');
  const n = await links.count();
  const out: BreakdownJob[] = [];
  for (let i = 0; i < n; i++) {
    const a = links.nth(i);
    const text = (await a.innerText()).replace(/\s+/g, ' ').trim();
    const no = text.match(/\b([A-Z]+-\d+)\s*·\s*(\d{2}\/\d{2}\/\d{2})/);
    const money = text.match(/\$[\d,]+(?:\.\d+)?\s*$/);
    out.push({
      href: (await a.getAttribute('href')) ?? '',
      jobNo: no?.[1] ?? '',
      date: no?.[2] ?? '',
      cents: money ? moneyToCents(money[0]) : NaN,
      text,
    });
  }
  return out;
}

/** Итог окна разбивки «Total · N $X» (EN). */
export async function readBreakdownTotal(dlg: Locator): Promise<{ count: number; cents: number }> {
  const text = (await dlg.innerText()).replace(/\s+/g, ' ');
  const m = text.match(/Total · (\d+) (\$[\d,]+(?:\.\d+)?)/);
  if (!m) throw new Error(`в окне разбивки нет «Total · N $X»: ${text}`);
  return { count: Number(m[1]), cents: moneyToCents(m[2]) };
}

/** Закрыть окно разбивки (Escape — без зависимости от языка подписи кнопки). */
export async function closeBreakdown(dlg: Locator) {
  await dlg.page().keyboard.press('Escape');
  await expect(dlg).toBeHidden();
}
